  const headers=["DIRECTION","CALL STATE","STREAM DURATION","HIGH CHANGE","TIME · MS","DATE · EASTERN","MARKET HOUR","SOURCE","DATUM / ALERT PRICE","SESSION TARGET","STRIKE / REFERENCE","DYNAMIC / EXTREME HIGH","TIME TO HIGH","DYNAMIC / EXTREME LOW","LOW CHANGE","TIME TO LOW","CURRENT / FINAL","CURRENT / FINAL CHANGE","STRONGEST GREEK","WEAKEST GREEK","INTENSITY","PRESSURE",...greekNames.flatMap(name=>[`${name.toUpperCase()} @ STRIKE · RAW`,`${name.toUpperCase()} @ STRIKE · NORM`,`${name.toUpperCase()} HIGH`,`${name.toUpperCase()} LOW`]),...["STRIKE","FINAL"].flatMap(phase=>GAMMA_RANKS.map(rank=>`${phase} · ${rank.toUpperCase()}`)),"EVENT ID"];
  const values=[biasLabel(call.direction),view.label,callStreamDuration(call),change(high),logTime(call.alerted_at),logDate(call.alerted_at),marketHourLabel(call.alerted_at),call.symbol,datum.toFixed(4),number(call.target_price,gammaReachFromDatum(datum,call.direction,call.alerted_at)).toFixed(4),`${strike.estimated?"REF ":""}${strike.value.toFixed(2)}`,Number.isFinite(high)?high.toFixed(4):"—",finished?duration(call.seconds_to_high):"TRACKING",Number.isFinite(low)?low.toFixed(4):"—",change(low),finished?duration(call.seconds_to_low):"TRACKING",Number.isFinite(current)?current.toFixed(4):"—",change(current),call.strongest_greek_current??call.strongest_greek??"—",call.weakest_greek_current??call.weakest_greek??"—",pct(event.intensity),Number.isFinite(event.pressure)?`${event.pressure>0?"+":""}${event.pressure.toFixed(2)}`:"—",...greekNames.flatMap(name=>{const signal=call.greek_values_at_signal?.[name]??event[name],normalized=snapshot.normalized?.[name]??event.normalized?.[name];return [signedGreek(signal),Number.isFinite(Number(normalized))?`${number(normalized)>=0?"+":""}${number(normalized).toFixed(3)}`:"—",signedGreek(call.greek_values_highest?.[name]??signal),signedGreek(call.greek_values_lowest?.[name]??signal)]}),...GAMMA_RANKS.map(rank=>rankingText(signalRanks,rank)),...GAMMA_RANKS.map(rank=>rankingText(finalRanks,rank)),event.id];
